<section class="section-wrap dashboard-page admin-page"><div class="dashboard-heading"><div><p class="eyebrow">THE PEOPLE BEHIND THE RITUALS</p><h1>Customers<span class="brand-dot">.</span></h1><p><?= count($users) ?> latest customer accounts.</p></div></div><div class="data-card"><div class="table-head customers-admin-head"><span>Customer</span><span>Contact</span><span>Location</span><span>Orders</span><span>Joined</span></div><?php foreach ($users as $customer): ?><div class="table-row customers-admin-head"><b><?= $e($customer['name']) ?><small>#<?= (int) $customer['id'] ?></small></b><span><?= $e($customer['email']) ?><small><?= $e($customer['phone'] ?? 'No phone added') ?></small></span><span><?= $e($customer['city'] ?? '—') ?></span><span><?= (int) $customer['order_count'] ?></span><span><?= $e(date('M j, Y', strtotime($customer['created_at']))) ?></span></div><?php endforeach; ?><?php if (!$users): ?><p class="empty-inline">Customer accounts will appear here.</p><?php endif; ?></div></section>
